// The "/eccx-loop-<category>" and "/eccx-<category>" commands on the "Vòng lặp" tab (owner 2026-11-03:
// "vòng lặp là có cả eccx-loop-* … hiển sẵn lệnh hướng dẫn có copy, gửi ngay vào phiên"). The files are
// generated by scripts/eccx-gen.py and installed in ~/.claude/commands (loops: Claude Code only, they ride
// CronCreate + /ship-tick) and ~/.omp/agent/commands; lib/server/eccx.ts reads them. Pure rules, no
// React, no node. Tested in tests/eccx.test.ts.

export type EccxEngine = "omp" | "claude";

export type EccxCommand = {
  /** File name without `.md`: `eccx-loop-frontend`, `eccx-frontend`, `eccx-clear`. */
  name: string;
  /** loop: `/eccx-loop-<cat>` · plan: `/eccx-<cat>` · util: anything else (`/eccx-clear`). */
  kind: "loop" | "plan" | "util";
  /** The category id (`frontend`); null for a util. */
  cat: string | null;
  /** The category title from the plan file's heading (`Ads & Marketing`), else the id. */
  title: string;
  /** The plan file's `Scope:` line (English, as generated); null when not found. */
  scope: string | null;
  /** Frontmatter `description` (English, as generated). */
  description: string;
  /** Frontmatter `argument-hint`, e.g. `<goal> [--max-iter 8] [--max-min 90] [--release] [--dry-run]`. */
  hint: string;
  /** Which engines have the file installed. */
  engines: EccxEngine[];
};

const KIND_ORDER = { loop: 0, plan: 1, util: 2 } as const;

/** `eccx-loop-<cat>` → loop, `eccx-<cat>` → plan when a loop or a scope names it a category, else util. */
export function eccxKind(name: string, isCategory: boolean): { kind: EccxCommand["kind"]; cat: string | null } {
  if (name.startsWith("eccx-loop-")) return { kind: "loop", cat: name.slice("eccx-loop-".length) };
  if (isCategory) return { kind: "plan", cat: name.slice("eccx-".length) };
  return { kind: "util", cat: null };
}

/** Loops first (owner's ask), then the one-shot plans, then utilities; by name inside each. */
export function sortEccx(list: EccxCommand[]): EccxCommand[] {
  return [...list].sort((a, b) => KIND_ORDER[a.kind] - KIND_ORDER[b.kind] || a.name.localeCompare(b.name));
}

/** The required part of the hint, in Vietnamese: `<goal>` → `<mục tiêu>`; flags in `[...]` go to [eccxFlags]. */
export function eccxArgs(hint: string): string {
  return hint
    .replace(/\[[^\]]*\]/g, "")
    .replace(/<goal>/g, "<mục tiêu>")
    .replace(/\s+/g, " ")
    .trim();
}

/** The optional flags of the hint (`[--max-iter 8]` …), joined by spaces. */
export function eccxFlags(hint: string): string {
  return (hint.match(/\[[^\]]*\]/g) ?? []).join(" ");
}

/** The ready-to-run example line shown and copied: `/eccx-loop-frontend <mục tiêu>`. */
export function eccxExample(c: Pick<EccxCommand, "name" | "hint">): string {
  const args = eccxArgs(c.hint);
  return args ? `/${c.name} ${args}` : `/${c.name}`;
}

/** What it does, one Vietnamese line. */
export function eccxLine(c: Pick<EccxCommand, "kind" | "name" | "cat" | "title">): string {
  if (c.kind === "loop") return `Lặp /eccx-${c.cat} tới khi mọi tiêu chí xanh.`;
  if (c.kind === "plan") return c.cat === "full" ? "Chạy một lần: chọn mọi nhóm liên quan tới mục tiêu rồi gộp kế hoạch của chúng." : `Chạy một lần kế hoạch ${c.title} với mọi skill ECC + 8 Sync hợp mục tiêu.`;
  if (c.name === "eccx-clear") return "Dừng các vòng lặp đang chạy (/eccx-loop-*, /ship-loop): tắt cron tick, đóng trạng thái, giữ bằng chứng.";
  return `Lệnh /${c.name}.`;
}

/** The engine a room runs, as the command folders name it (Room.engine: "ccc" | "omp"). */
export const roomEngine = (engine: string): EccxEngine => (engine === "omp" ? "omp" : "claude");

/** Whether a room can run the command: its engine has the file installed. */
export function eccxReaches(c: Pick<EccxCommand, "engines">, engine: string): boolean {
  return c.engines.includes(roomEngine(engine));
}

/** Where the engine keeps the command file (named to the room when the slash cannot expand). */
export function eccxPath(name: string, engine: EccxEngine): string {
  return engine === "omp" ? `~/.omp/agent/commands/${name}.md` : `~/.claude/commands/${name}.md`;
}

/**
 * The text sent into the room. Typed into a terminal, `/cmd goal` runs as a slash command. An inbox
 * message reaches the room inside HQ's framing (crates/cli/src/verbs/hq.rs `frame`), where a slash
 * does not expand: a second line names the file to follow and the goal it takes.
 */
export function eccxMessage(name: string, goal: string, room: { delivery: "terminal" | "inbox" | null; engine: string }): string {
  const g = goal.trim().replace(/\s+/g, " ");
  const line = g ? `/${name} ${g}` : `/${name}`;
  if (room.delivery !== "inbox") return line;
  return `${line}\n(Lệnh slash tới qua inbox nên không tự chạy: đọc ${eccxPath(name, roomEngine(room.engine))} và làm theo, $ARGUMENTS = ${JSON.stringify(g)}.)`;
}
